const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centerPoint = ee.Geometry.Point([-112.246886, 34.498828]);
  const aoi = centerPoint.buffer(80467); // 50 miles is approx 80,467 meters
  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  // 2. Data Acquisition
  // MODIS Thermal Anomalies & Fire product is ideal for this. It's a collection of points.
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14DL')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // 3. Processing & Calculation
  // We just need to count the number of fire detection points within the collection.
  // The 'MaxFRP' band contains the fire radiative power, which is a good indicator.
  // We'll convert the ImageCollection to a FeatureCollection of points.
  const firePoints = fireCollection.map(function(image) {
    // Select the fire mask band and create points where fires are detected.
    return image.select('MaxFRP')
      .gt(0) // Filter for pixels with fire radiative power > 0
      .selfMask() // Mask out non-fire pixels
      .reduceToVectors({
        geometry: aoi,
        scale: 1000, // MODIS resolution
        geometryType: 'centroid',
        eightConnected: false,
      });
  }).flatten(); // Combine features from all images into one collection.


  const fireCount = firePoints.size().getInfo();

  // 4. Validation & Final Answer
  console.log(`Query Period: ${startDate} to ${endDate}`);
  console.log(`Area: 50-mile radius around (${centerPoint.coordinates().get(1).getInfo().toFixed(4)}, ${centerPoint.coordinates().get(0).getInfo().toFixed(4)})`);
  console.log(`MODIS Fire Detections: ${fireCount}`);

  if (fireCount === null || isNaN(fireCount)) {
    console.log("Calculation failed: Could not determine the number of fire points.");
    console.log("C3");
  } else if (fireCount > 0) {
    console.log("Evidence: Fire activity was detected within the specified area and time frame.");
    console.log("A");
  } else {
    console.log("Evidence: No fire activity was detected by MODIS in the specified area and time frame.");
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
